pm.test("Every user in data array has required fields", function () {
    const json = pm.response.json();

    json.data.forEach(function (user, index) {
        pm.expect(user).to.have.property('id');
        pm.expect(user).to.have.property('name');
        pm.expect(user).to.have.property('year');
        pm.expect(user).to.have.property('color');

        if (user.hasOwnProperty('avatar')) {
            pm.expect(user.avatar).to.be.a('string');
        } else {
            console.log(`User index ${index} (id: ${user.id}) tidak punya field avatar`);
        }
    });
});

